import { API_PREFIX } from "@/lib/constants";

export class ApiError extends Error {
  constructor(
    public status: number,
    public detail: string,
  ) {
    super(detail);
    this.name = "ApiError";
  }
}

function getBaseUrl(): string {
  return localStorage.getItem("erock_api_url") || "";
}

function getApiKey(): string {
  return localStorage.getItem("erock_api_key") || "";
}

export async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(options?.headers as Record<string, string> | undefined),
  };
  const key = getApiKey();
  if (key) {
    headers["X-API-Key"] = key;
  }

  const res = await fetch(`${getBaseUrl()}${API_PREFIX}${path}`, {
    ...options,
    headers,
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({ detail: res.statusText }));
    throw new ApiError(res.status, body.detail || body.error || res.statusText);
  }

  if (res.status === 204) return undefined as T;
  return res.json();
}

/** Test backend connectivity via /health endpoint. */
export async function testConnection(baseUrl?: string): Promise<{ ok: true; version: string } | { ok: false; error: string }> {
  try {
    const base = baseUrl ?? getBaseUrl();
    const res = await fetch(`${base}/health`, {
      method: "GET",
      headers: { "Content-Type": "application/json" },
    });
    if (!res.ok) {
      return { ok: false, error: `HTTP ${res.status}` };
    }
    const data = await res.json();
    return { ok: true, version: data.version ?? "unknown" };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

/** Detailed status response from /api/v1/status/detailed. */
export interface DetailedStatus {
  version: string;
  provider: string;
  db_status: string;
}

/** Fetch detailed status from the backend. */
export async function getDetailedStatus(): Promise<DetailedStatus> {
  return apiFetch<DetailedStatus>("/status/detailed");
}

export function sseUrl(path: string): string {
  const base = getBaseUrl() || window.location.origin;
  const key = getApiKey();
  const separator = path.includes("?") ? "&" : "?";
  const auth = key ? `${separator}api_key=${encodeURIComponent(key)}` : "";
  return `${base}${API_PREFIX}${path}${auth}`;
}

import { apiFetch } from "./client";
import type { KnowledgeSearchResponse } from "./types";

export function searchKnowledge(query: string, topK = 20): Promise<KnowledgeSearchResponse> {
  return apiFetch("/knowledge/search", {
    method: "POST",
    body: JSON.stringify({ query, top_k: topK }),
  });
}

// --- Pipeline ---

export interface PipelineRunRequest {
  domain?: string;
  max_gaps?: number;
  generation_rounds?: number | null;
  ideas_per_round?: number | null;
  search_queries?: string[] | null;
  run_novelty?: boolean;
  run_feasibility?: boolean;
  run_synthesis?: boolean;
  export_format?: string;
}

export interface PipelineRunSummary {
  id: number;
  status: "pending" | "running" | "completed" | "failed";
  domain: string;
  current_stage: string | null;
  ideas_count: number;
  created_at: string;
  completed_at: string | null;
  error_message: string | null;
}

export interface PipelineRunDetail extends PipelineRunSummary {
  config: Record<string, unknown>;
  stages_completed: string[];
  ideas: IdeaSummary[];
}

export interface TriggerRunResponse {
  run_id: string;
  status: string;
}

export interface AutonomousCycleRequest {
  domain?: string;
  max_runs?: number;
}

export interface AutonomousCycleResponse {
  cycle_id: string;
  status: string;
  domain: string;
  max_runs: number;
}

// --- SSE ---

export interface StageProgressEvent {
  stage: string;
  index: number;
  total: number;
  elapsed: number;
}

export interface ProgressDoneEvent {
  done: true;
}

export interface HeartbeatEvent {
  heartbeat: true;
}

export type ProgressEvent = StageProgressEvent | ProgressDoneEvent | HeartbeatEvent;

// --- Ideas ---

export interface IdeaSummary {
  id: number;
  title: string;
  domain: string;
  novelty_score: number | null;
  feasibility_score: number | null;
  overall_score: number | null;
  source_gap_ids: string[] | null;
  has_proposal: boolean;
  pipeline_run_id: number | null;
  created_at: string;
}

export interface IdeaDetail extends IdeaSummary {
  problem_statement: string;
  proposed_method: string;
  expected_contributions: string;
  source_gap_ids: string[] | null;
  novelty_report: Record<string, unknown> | null;
  feasibility_report: Record<string, unknown> | null;
  proposal_md: string | null;
  proposal_latex: string | null;
  proposal_sections: Record<string, unknown> | null;
}

export interface IdeaListResponse {
  ideas: IdeaSummary[];
  total: number;
  score_guide: Record<string, Record<string, string>>;
}

export interface IdeaFeedbackRequest {
  rating: number;
  notes?: string | null;
}

// --- Gaps ---

export interface ResearchGap {
  id: number;
  title: string;
  description: string;
  gap_type: string;
  confidence: number;
  potential_impact: string;
  idea_count: number;
}

export interface GapListResponse {
  gaps: ResearchGap[];
  total: number;
}

// --- Knowledge ---

export interface KnowledgeSearchResult {
  id: string;
  text: string;
  metadata: Record<string, string>;
  distance: number;
}

export interface KnowledgeSearchResponse {
  query: string;
  results: KnowledgeSearchResult[];
}

// --- Status ---

export interface SystemStatus {
  app_name: string;
  version: string;
  config: Record<string, boolean>;
  defaults: Record<string, number>;
}

import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { ResearchGap } from "@/api/types";
import { cn } from "@/lib/utils";
import { Lightbulb } from "lucide-react";

interface GapCardProps {
  gap: ResearchGap;
  onIdeaCountClick?: (gap: ResearchGap) => void;
}

function confidenceColor(confidence: number): string {
  if (confidence >= 0.8) return "bg-green-500";
  if (confidence >= 0.6) return "bg-emerald-500";
  if (confidence >= 0.3) return "bg-amber-500";
  return "bg-red-500";
}

export function GapCard({ gap, onIdeaCountClick }: GapCardProps) {
  const ideaCount = gap.idea_count ?? 0;

  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <h3 className="text-sm font-medium leading-tight">{gap.title}</h3>
            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{gap.description}</p>
            <div className="flex items-center gap-2 mt-2">
              <Badge variant="outline" className="text-xs">
                {gap.gap_type}
              </Badge>
              {gap.potential_impact && (
                <span className="text-xs text-muted-foreground">{gap.potential_impact}</span>
              )}
              {ideaCount > 0 && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onIdeaCountClick?.(gap);
                  }}
                  className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2 py-0.5 text-xs font-medium text-amber-800 hover:bg-amber-200 transition-colors cursor-pointer"
                  aria-label={`${ideaCount} idea${ideaCount !== 1 ? "s" : ""} generated`}
                >
                  <Lightbulb className="h-3 w-3" />
                  {ideaCount} idea{ideaCount !== 1 ? "s" : ""}
                </button>
              )}
            </div>
          </div>
          <div className="flex-shrink-0 flex flex-col items-center gap-1">
            <span className="text-xs text-muted-foreground">
              {(gap.confidence * 100).toFixed(0)}%
            </span>
            <div className="h-2 w-16 rounded-full bg-secondary overflow-hidden">
              <div
                className={cn("h-full rounded-full", confidenceColor(gap.confidence))}
                style={{ width: `${gap.confidence * 100}%` }}
              />
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { GapCard } from "@/components/gaps/gap-card";
import type { ResearchGap } from "@/api/types";

const sampleGap: ResearchGap = {
  id: 1,
  title: "Lack of cross-lingual transfer methods",
  description: "No methods exist for transferring knowledge between typologically distant languages.",
  gap_type: "methodological",
  confidence: 0.75,
  potential_impact: "High",
  idea_count: 0,
};

describe("GapCard", () => {
  it("renders gap title, description, and type badge", () => {
    render(<GapCard gap={sampleGap} />);
    expect(screen.getByText("Lack of cross-lingual transfer methods")).toBeInTheDocument();
    expect(screen.getByText(/No methods exist/)).toBeInTheDocument();
    expect(screen.getByText("methodological")).toBeInTheDocument();
  });

  it("shows confidence percentage", () => {
    render(<GapCard gap={sampleGap} />);
    expect(screen.getByText("75%")).toBeInTheDocument();
  });

  it("renders confidence bar with correct width", () => {
    const { container } = render(<GapCard gap={sampleGap} />);
    const bar = container.querySelector('[style*="width"]');
    expect(bar).toBeTruthy();
    expect(bar?.getAttribute("style")).toContain("75%");
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { MemoryRouter } from "react-router-dom";
import KnowledgeSearch from "@/pages/knowledge-search";
import type { KnowledgeSearchResponse } from "@/api/types";

// ── Mock API (AR-03) ─────────────────────────────────────────────
vi.mock("@/api/knowledge", () => ({
  searchKnowledge: vi.fn(),
}));

import { searchKnowledge } from "@/api/knowledge";

const mockedSearchKnowledge = vi.mocked(searchKnowledge);

function createQueryClient() {
  return new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  });
}

function renderKnowledgeSearch() {
  const qc = createQueryClient();
  return render(
    <QueryClientProvider client={qc}>
      <MemoryRouter>
        <KnowledgeSearch />
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

const sampleResponse: KnowledgeSearchResponse = {
  query: "transformer attention",
  results: [
    {
      id: "doc-1",
      text: "Attention is all you need. Transformer architecture overview.",
      metadata: { source: "arxiv", year: "2017", authors: "Vaswani et al." },
      distance: 0.15,
    },
    {
      id: "doc-2",
      text: "Multi-head attention allows the model to jointly attend to information.",
      metadata: { source: "neurips", year: "2017" },
      distance: 0.42,
    },
  ],
};

beforeEach(() => {
  vi.clearAllMocks();
});

describe("KnowledgeSearch", () => {
  // ── TEST-11-01-16: Renders search form ──────────────────────────
  it("TEST-11-01-16: renders search form", () => {
    renderKnowledgeSearch();

    expect(screen.getByText("Knowledge Base")).toBeInTheDocument();
    expect(screen.getByPlaceholderText("Search papers, methods, findings...")).toBeInTheDocument();
  });

  // ── TEST-11-01-17: Shows search results ─────────────────────────
  it("TEST-11-01-17: shows search results after submission", async () => {
    const user = userEvent.setup();
    mockedSearchKnowledge.mockResolvedValue(sampleResponse);

    renderKnowledgeSearch();

    const input = screen.getByPlaceholderText("Search papers, methods, findings...");
    await user.type(input, "transformer attention");
    await user.keyboard("{Enter}");

    await waitFor(() => {
      expect(screen.getByText(/2 results for/)).toBeInTheDocument();
    });

    // First result text is rendered
    expect(
      screen.getByText("Attention is all you need. Transformer architecture overview."),
    ).toBeInTheDocument();

    // Badges — source badge is unique
    expect(screen.getByText("arxiv")).toBeInTheDocument();
    // Year "2017" appears in both results
    expect(screen.getAllByText("2017").length).toBe(2);
  });
});

import { Routes, Route, Navigate } from "react-router-dom";
