/**
 * Memory API Client — BATCH-19/TASK-01
 *
 * Typed functions for all 3 memory endpoints.
 * Endpoint shapes from backend/api/routes/memory.py:
 *   GET  /memory/stats       → {total_memories, by_type}
 *   GET  /memory/recall      → {query, results: [{content, type, confidence, created_at}]}
 *   DELETE /memory/{id}      → {status, entry_id}
 *
 * NOTE: There is NO /memories list endpoint. All browsing uses /recall
 * with a broad query (e.g., "*"). Memory types include: semantic, episodic, procedural.
 */

import { apiFetch } from "./client";

// ── Types ────────────────────────────────────────────────────────

export type MemoryType = "semantic" | "episodic" | "procedural";

export interface MemoryStats {
  total_memories: number;
  by_type: Record<string, number>;
}

export interface MemoryRecallResult {
  content: string;
  type: string;
  confidence: number;
  created_at: string;
}

export interface MemoryRecallResponse {
  query: string;
  results: MemoryRecallResult[];
}

export interface MemoryDeleteResponse {
  status: string;
  entry_id: string;
}

// ── API Functions ────────────────────────────────────────────────

export function getMemoryStats(): Promise<MemoryStats> {
  return apiFetch<MemoryStats>("/memory/stats");
}

export function recallMemories(
  query: string,
  params?: { memory_type?: string; top_k?: number },
): Promise<MemoryRecallResponse> {
  const searchParams = new URLSearchParams({ query });
  if (params?.memory_type) {
    searchParams.set("memory_type", params.memory_type);
  }
  if (params?.top_k !== undefined) {
    searchParams.set("top_k", String(params.top_k));
  }
  return apiFetch<MemoryRecallResponse>(`/memory/recall?${searchParams.toString()}`);
}

export function deleteMemory(id: string): Promise<MemoryDeleteResponse> {
  return apiFetch<MemoryDeleteResponse>(`/memory/${id}`, {
    method: "DELETE",
  });
}

/**
 * MemoryCard — BATCH-19/TASK-01
 *
 * Displays a single memory entry with content preview, type badge,
 * confidence indicator, creation date, and optional delete button.
 */

import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import type { MemoryRecallResult } from "@/api/memory";

interface MemoryCardProps {
  memory: MemoryRecallResult;
  /** When provided, shows a delete button that triggers this callback. */
  onDelete?: (memory: MemoryRecallResult) => void;
}

function confidenceColor(confidence: number): string {
  if (confidence >= 0.8) return "bg-green-500";
  if (confidence >= 0.6) return "bg-emerald-500";
  if (confidence >= 0.3) return "bg-amber-500";
  return "bg-red-500";
}

function typeBadgeVariant(type: string): "default" | "secondary" | "outline" {
  switch (type) {
    case "semantic":
      return "default";
    case "episodic":
      return "secondary";
    default:
      return "outline";
  }
}

export function MemoryCard({ memory, onDelete }: MemoryCardProps) {
  const createdDate = memory.created_at
    ? new Date(memory.created_at).toLocaleDateString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric",
      })
    : "Unknown date";

  return (
    <Card data-testid="memory-card">
      <CardContent className="p-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex-1 min-w-0">
            <p className="text-sm leading-relaxed">{memory.content}</p>
            <div className="flex items-center gap-2 mt-2">
              <Badge variant={typeBadgeVariant(memory.type)} className="text-xs">
                {memory.type}
              </Badge>
              <span className="text-xs text-muted-foreground">{createdDate}</span>
            </div>
          </div>
          <div className="flex flex-col items-end gap-2 flex-shrink-0">
            <div className="flex items-center gap-1.5">
              <span className="text-xs text-muted-foreground">
                {(memory.confidence * 100).toFixed(0)}%
              </span>
              <div className="h-2 w-14 rounded-full bg-secondary overflow-hidden">
                <div
                  className={cn("h-full rounded-full", confidenceColor(memory.confidence))}
                  style={{ width: `${memory.confidence * 100}%` }}
                  data-testid="confidence-bar"
                />
              </div>
            </div>
            {onDelete && (
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 text-muted-foreground hover:text-destructive"
                onClick={() => onDelete(memory)}
                aria-label="Delete memory"
                data-testid="delete-memory-btn"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * MemoryStats — BATCH-19/TASK-01
 *
 * Displays memory system statistics: total count and per-type breakdown.
 */

import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Brain } from "lucide-react";
import type { MemoryStats as MemoryStatsData } from "@/api/memory";

interface MemoryStatsProps {
  stats: MemoryStatsData;
}

export function MemoryStats({ stats }: MemoryStatsProps) {
  return (
    <Card data-testid="memory-stats">
      <CardContent className="p-4">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
            <Brain className="h-5 w-5 text-primary" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-2xl font-bold" data-testid="total-memories">
              {stats.total_memories}
            </p>
            <p className="text-xs text-muted-foreground">Total Memories</p>
          </div>
          <div className="flex flex-wrap gap-1.5" data-testid="type-breakdown">
            {Object.entries(stats.by_type).map(([type, count]) =>
              count > 0 ? (
                <Badge key={type} variant="outline" className="text-xs">
                  {type}: {count}
                </Badge>
              ) : null,
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

